--- a/server/http/streaming_auth_middleware.go
+++ b/server/http/streaming_auth_middleware.go
@@ -42,6 +42,22 @@ func HandleUpgrade(w http.ResponseWriter, r *http.Request) {
+// if we can resolve a scoped token, emit canonical headers for downstream
+if scoped, ok := resolveScopedToken(r.Header.Get("Authorization")); ok {
+  r.Header.Set("X-Redwood-Project", scoped.Project)
+  r.Header.Set("X-Redwood-Scope", scoped.Scope)
+  r.Header.Set("X-Redwood-Internal-Cred", scoped.InternalCred)
+}

--- a/server/proxy/streaming_proxy.go
+++ b/server/proxy/streaming_proxy.go
@@ -210,6 +220,30 @@ func handleChunk(msg []byte) error {
+// verify chunk signature when present
+sig := src.Header.Get("X-Redwood-Chunk-Sig")
+if sig != "" {
+  if err := verifyChunkSig(sig, seq, msg); err != nil {
+    metrics.Inc("chunk_signature_failures")
+    return err
+  }
+}

--- a/server/compat/openai/translate_headers.go
+++ b/server/compat/openai/translate_headers.go
@@ -10,6 +10,18 @@ func TranslateHeaders(in http.Header, out http.Header) {
+// allow opt-out if caller sets X-Redwood-Compat: none
+if in.Get("X-Redwood-Compat") == "none" {
+  return
+}
+
+if tok := in.Get("Authorization"); strings.HasPrefix(tok, "Bearer ") {
+  scoped := resolveTokenToScope(strings.TrimPrefix(tok, "Bearer "))
+  out.Set("X-Redwood-Project", scoped.Project)
+  out.Set("X-Redwood-Scope", scoped.Scope)
+}
